import AppKit
import Testing
@testable import TerminalUI

@Test @MainActor
func dismantleAfterSwapUsesCurrentTerminal() {
    let x = TerminalCoordinator()
    let y = TerminalCoordinator()
    let container = NSView()
    let oldTile = NSView()
    let initialCoordinator = TerminalView(coordinator: x).makeCoordinator()

    #expect(TerminalMount.attach(x.hostingView, to: container))
    #expect(TerminalMount.attach(y.hostingView, to: oldTile))
    #expect(TerminalMount.attach(y.hostingView, to: container))

    // SwiftUI の破棄引数は makeCoordinator 時点の X。
    withExtendedLifetime(container) {
        TerminalView.dismantleNSView(container, coordinator: initialCoordinator)
        #expect(y.hostingView.superview == nil)
        #expect(container.subviews.isEmpty)
        #expect(TerminalMount.attach(y.hostingView, to: oldTile))
        #expect(y.hostingView.superview === oldTile)
    }
}
